/* Mat's Interview Lab — static, dependency-free, GitHub Pages ready. */
'use strict';

const QUESTIONS = [
  { id:1, category:'Fundamentals', type:'tf', difficulty:'Beginner', prompt:'A function must use console.log() to send a value back to the code that called it.', correct:1, explanation:'False. console.log() displays information in the console. A return statement sends a value back to the caller. A function can return a value without printing anything.', followUp:'What would happen if you called a function that prints 5 but does not return anything?' },
  { id:2, category:'Fundamentals', type:'tf', difficulty:'Beginner', prompt:'If an object is stored in a const variable, its properties can never change.', correct:1, explanation:'False. const prevents reassigning the variable to a different value. It does not freeze the object. You can usually update the properties of an object held by a const variable.', followUp:'What is the difference between changing order.total and assigning order = {}?' },
  { id:3, category:'Fundamentals', type:'tf', difficulty:'Beginner', prompt:'The === operator compares values without performing type conversion.', correct:0, explanation:'True. Strict equality does not coerce different types into matching types. For example, 5 === "5" is false.', followUp:'How would 5 == "5" behave differently?' },
  { id:4, category:'Fundamentals', type:'tf', difficulty:'Intermediate', prompt:'In JavaScript, an empty array [] is truthy.', correct:0, explanation:'True. Arrays and objects are truthy even when empty. Boolean([]) is true. To check whether an array contains items, use array.length > 0.', followUp:'What is Boolean([]) compared with Boolean("")?' },
  { id:5, category:'Functions & Strings', type:'tf', difficulty:'Beginner', prompt:'A parameter and an argument mean exactly the same thing.', correct:1, explanation:'False. A parameter is the named placeholder in a function definition. An argument is the actual value supplied when you call the function.', followUp:'In makeBurger("Mat"), which is the argument: name or "Mat"?' },
  { id:6, category:'Arrays & Objects', type:'tf', difficulty:'Beginner', prompt:'Array.map() returns a new array with the same number of elements as the original array.', correct:0, explanation:'True. map runs a callback once per element and collects the returned value for each position. It does not remove elements; use filter when you want to keep only some.', followUp:'What happens when a map callback forgets to return?' },
  { id:7, category:'Arrays & Objects', type:'tf', difficulty:'Beginner', prompt:'Array.filter() changes the original array by deleting items that do not match.', correct:1, explanation:'False. filter returns a new array of matching elements and does not delete elements from the original array. The objects inside those arrays can still be shared references.', followUp:'Which array would you use if you only wanted orders over $20?' },
  { id:8, category:'Functions & Strings', type:'tf', difficulty:'Beginner', prompt:'Executing return inside a function ends that call to the function immediately.', correct:0, explanation:'True. Once return executes, control goes back to the caller. Any statements after that return in the same path do not run.', followUp:'Would console.log placed after return execute?' },
  { id:9, category:'Arrays & Objects', type:'tf', difficulty:'Beginner', prompt:'Array.find() returns an array containing every matching element.', correct:1, explanation:'False. find returns the first matching element, or undefined if none match. filter returns an array containing all matches.', followUp:'What does find return if there are no matching orders?' },
  { id:10, category:'Interview Thinking', type:'tf', difficulty:'Beginner', prompt:'If AI-generated code runs without an error, that proves it meets the requirements.', correct:1, explanation:'False. Code may run perfectly and still produce the wrong result, mishandle edge cases, or change data it should leave untouched. Verify behavior using tests and the stated requirements.', followUp:'What tests would you write for a function that counts the letter E?' },
  { id:11, category:'Fundamentals', type:'tf', difficulty:'Beginner', prompt:'A variable declared with let inside a block is accessible everywhere outside that block.', correct:1, explanation:'False. let is block-scoped. A let variable created inside a block (for example, inside an if statement) cannot be used outside that block.', followUp:'Why might a variable created inside an if block cause a ReferenceError later?' },
  { id:12, category:'Fundamentals', type:'tf', difficulty:'Beginner', prompt:'A for...of loop over an array gives you its element values.', correct:0, explanation:'True. for...of iterates values in an array, such as each order total. A traditional indexed for loop can be used when you need the position.', followUp:'Would for...of over [10, 20] give 10 and 20, or 0 and 1?' },
  { id:13, category:'Fundamentals', type:'predict', difficulty:'Beginner', prompt:'What does this print?', code:'let total = 3;\ntotal += 2;\nconsole.log(total);', choices:['3','5','32','undefined'], correct:1, explanation:'The += operator adds the right-hand value to the current number and stores the result. 3 + 2 is 5.', followUp:'What changes if total starts as the string "3"?' },
  { id:14, category:'Functions & Strings', type:'predict', difficulty:'Beginner', prompt:'What is printed by this function call?', code:'function multiply(a, b) {\n  return a * b;\n}\nconsole.log(multiply(2, 3));', choices:['23','6','undefined','NaN'], correct:1, explanation:'The arguments 2 and 3 are placed into parameters a and b. The function returns 2 * 3, which is 6.', followUp:'What would multiply(4, 5) return?' },
  { id:15, category:'Functions & Strings', type:'predict', difficulty:'Beginner', prompt:'What does the string method produce?', code:'console.log("burger".toUpperCase());', choices:['burger','Burger','BURGER','undefined'], correct:2, explanation:'toUpperCase() returns a new string containing uppercase versions of the letters. It does not change the original string.', followUp:'What happens if you call toUpperCase() but do not store or print the result?' },
  { id:16, category:'Functions & Strings', type:'predict', difficulty:'Beginner', prompt:'Which part of the string does slice return?', code:'console.log("Cheese".slice(0, 3));', choices:['Che','Chee','ese','C'], correct:0, explanation:'slice(0, 3) starts at index 0 and stops just before index 3, returning the first three characters: C, h, and e.', followUp:'What would slice(1, 4) return?' },
  { id:17, category:'Functions & Strings', type:'predict', difficulty:'Beginner', prompt:'What are the two console lines, in order?', code:'function total(a, b) {\n  console.log(a + b);\n}\nconsole.log(total(2, 3));', choices:['5, then 5','undefined, then 5','5, then undefined','No output'], correct:2, explanation:'The function first prints 5 internally. Because it has no return statement, its returned value is undefined, which the outer console.log prints next.', followUp:'What would you replace the inner console.log with to return 5?' },
  { id:18, category:'Arrays & Objects', type:'predict', difficulty:'Beginner', prompt:'What does this print?', code:'const items = ["fries", "soup", "steak"];\nconsole.log(items.length);', choices:['2','3','4','undefined'], correct:1, explanation:'length is the number of array elements. This array contains three items, even though the last valid index is 2.', followUp:'What is the index of "steak"?' },
  { id:19, category:'Arrays & Objects', type:'mcq', difficulty:'Beginner', prompt:'You need a new array containing only orders over $20. Which method best matches that requirement?', choices:['map()','filter()','find()','push()'], correct:1, explanation:'filter() returns every element that meets a condition. map() transforms each element; find() returns only the first match; push() adds an element.', followUp:'How would the behavior change if you used find instead?' },
  { id:20, category:'Arrays & Objects', type:'predict', difficulty:'Intermediate', prompt:'What does this print?', code:'const prices = [10, 20];\nconst doubled = prices.map(price => price * 2);\nconsole.log(doubled);', choices:['[10, 20]','[20, 40]','[true, true]','40'], correct:1, explanation:'map() applies the callback to both elements and collects their returned results. The new array contains 20 and 40; prices remains unchanged.', followUp:'Would prices itself still be [10, 20] afterward?' },
  { id:21, category:'Arrays & Objects', type:'predict', difficulty:'Intermediate', prompt:'What will this code print?', code:'const orders = [{id:1,total:10},{id:2,total:35},{id:3,total:40}];\nconsole.log(orders.find(o => o.total > 20).id);', choices:['[2, 3]','3','2','undefined'], correct:2, explanation:'find() returns the first matching object, the order with id 2 and total 35. Accessing .id prints 2.', followUp:'How would you get both matching order objects?' },
  { id:22, category:'Arrays & Objects', type:'predict', difficulty:'Intermediate', prompt:'What does push() return?', code:'const foods = ["rice", "beans"];\nconsole.log(foods.push("salsa"));', choices:['salsa','3','["rice", "beans", "salsa"]','undefined'], correct:1, explanation:'push() adds the item to the existing array but returns the new array length, which is 3.', followUp:'What does console.log(foods) print afterward?' },
  { id:23, category:'Fundamentals', type:'predict', difficulty:'Beginner', prompt:'What does typeof report?', code:'console.log(typeof "42");', choices:['number','string','integer','object'], correct:1, explanation:'The quotation marks make "42" a string. typeof returns the text "string".', followUp:'What happens with typeof 42 without quotes?' },
  { id:24, category:'Fundamentals', type:'predict', difficulty:'Beginner', prompt:'What does JavaScript print here?', code:'console.log("5" + 2);', choices:['7','52','NaN','An error'], correct:1, explanation:'With a string as an operand, + performs string concatenation here. The number 2 is converted to text, giving "52".', followUp:'How could you convert "5" to a number before adding?' },
  { id:25, category:'Fundamentals', type:'mcq', difficulty:'Intermediate', prompt:'Which expression evaluates to false?', choices:['5 == "5"','Boolean([])','5 === "5"','10 > 2'], correct:2, explanation:'5 === "5" is false because the values have different types. Loose equality may convert types, and empty arrays are truthy.', followUp:'Why do developers generally prefer strict equality?' },
  { id:26, category:'Arrays & Objects', type:'predict', difficulty:'Beginner', prompt:'What number is printed?', code:'const amounts = [4, 7, 9];\nconsole.log(amounts[1]);', choices:['4','7','9','undefined'], correct:1, explanation:'Array indexes begin at zero. Index 0 has 4, index 1 has 7, and index 2 has 9.', followUp:'What would amounts[3] return?' },
  { id:27, category:'Fundamentals', type:'predict', difficulty:'Beginner', prompt:'Which message is printed?', code:'const score = 70;\nif (score >= 80) {\n  console.log("Great");\n} else {\n  console.log("Keep practicing");\n}', choices:['Great','Keep practicing','Both messages','Nothing'], correct:1, explanation:'70 is not greater than or equal to 80, so the else branch runs.', followUp:'What would happen if score were exactly 80?' },
  { id:28, category:'Debugging & Testing', type:'mcq', difficulty:'Beginner', prompt:'Which loop condition avoids going one index past the end of the array?', code:'const prices = [5, 10];\nfor (let i = 0; /* condition */; i++) {\n  console.log(prices[i]);\n}', choices:['i <= prices.length','i < prices.length','i > prices.length','i === prices.length'], correct:1, explanation:'The valid indexes for a two-item array are 0 and 1. i < prices.length stops before i reaches 2, avoiding an undefined element.', followUp:'What gets printed if you accidentally use <= instead?' },
  { id:29, category:'Debugging & Testing', type:'predict', difficulty:'Intermediate', prompt:'What does this map call produce?', code:'const result = [2, 4].map(n => {\n  n * 2;\n});\nconsole.log(result);', choices:['[4, 8]','[2, 4]','[undefined, undefined]','An error'], correct:2, explanation:'With braces, an arrow function needs an explicit return. Without it, each callback returns undefined, so map collects [undefined, undefined].', followUp:'How would you fix it with return? How could you fix it without braces?' },
  { id:30, category:'Debugging & Testing', type:'mcq', difficulty:'Beginner', prompt:'The code executes without throwing but shows the wrong restaurant total. What should you do first?', choices:['Deploy it because it runs','Clarify expected output and reproduce the problem with a test','Rewrite the whole app','Ask AI for the answer without checking'], correct:1, explanation:'Start by confirming the requirement and finding a reproducible example. A program running successfully does not prove that it is correct.', followUp:'Which input and expected output would make a good test case?' },
  { id:31, category:'Interview Thinking', type:'mcq', difficulty:'Beginner', prompt:'An interviewer says, “Count the letter E in a sentence.” What is the strongest first response?', choices:['Immediately write a loop','Ask whether uppercase E counts and how to handle an empty string','Say it is too easy','Open an AI chatbot without checking the interview policy'], correct:1, explanation:'Clarifying requirements before coding demonstrates deliberate problem-solving. Case sensitivity and empty inputs can change the implementation and tests.', followUp:'What output should the function return: a number or a modified string?' },
  { id:32, category:'Interview Thinking', type:'mcq', difficulty:'Beginner', prompt:'You are stuck during a live coding interview. What is generally the strongest approach?', choices:['Stay silent until time runs out','Explain what you understand, describe the next smaller step, and ask a targeted question','Pretend the code works','Change the subject'], correct:1, explanation:'Communicating your reasoning, reducing the problem, and requesting focused clarification helps the interviewer understand your approach, even when you do not finish.', followUp:'What would you say if you knew how to count E but not how to remove it?' },
  { id:33, category:'Arrays & Objects', type:'predict', difficulty:'Intermediate', prompt:'What does this print?', code:'const order = { total: 20 };\nconst copy = order;\ncopy.total = 30;\nconsole.log(order.total);', choices:['20','30','undefined','An error'], correct:1, explanation:'The two variables refer to the same object. Changing the property through copy also changes what you see through order.', followUp:'How might you make a separate shallow copy of the object?' },
  { id:34, category:'Arrays & Objects', type:'predict', difficulty:'Beginner', prompt:'What does this print?', code:'const numbers = [1, 2];\nconst doubled = numbers.map(n => n * 2);\nconsole.log(numbers);', choices:['[2, 4]','[1, 2]','[]','undefined'], correct:1, explanation:'map() constructs a new array. This callback multiplies numeric values, so the original numbers array stays [1, 2].', followUp:'What would console.log(doubled) print?' },
  { id:35, category:'Debugging & Testing', type:'mcq', difficulty:'Beginner', prompt:'Which input is the most useful edge case for a function that finds the largest number in an array?', choices:['[3, 8, 4]','[5, 2, 9]','[]','[100, 10, 2]'], correct:2, explanation:'An empty array challenges assumptions about there always being a first element. You should define how the function behaves when there are no values.', followUp:'Should it return null, undefined, or throw? How would you decide?' },
  { id:36, category:'Debugging & Testing', type:'mcq', difficulty:'Intermediate', prompt:'A developer was asked to return only matching orders, but their code returns true and false values. What is the most likely issue?', choices:['They used map() when they needed filter()','They used const','They used a for...of loop','They returned an array'], correct:0, explanation:'map() collects whatever the callback returns. A condition such as order.total > 20 returns booleans. filter() uses that condition to select matching original elements.', followUp:'When would returning an array of booleans be useful?' },
  { id:37, category:'Interview Thinking', type:'mcq', difficulty:'Beginner', prompt:'Which is a good way to discuss a project you built?', choices:['List every technology you have heard of','Explain the problem, your contribution, a difficult decision, and what you learned','Say AI did everything','Only discuss how it looked'], correct:1, explanation:'Interviewers benefit from concrete examples of your own role and decisions. The problem, action, result, and learning show what you can contribute.', followUp:'What is one real bug Mat fixed in a class project?' },
  { id:38, category:'Interview Thinking', type:'mcq', difficulty:'Beginner', prompt:'If an interviewer permits AI tools, what remains your responsibility?', choices:['Nothing, if AI wrote it','Understanding, verifying, and testing the submitted solution','Memorizing only the prompt','Avoiding all comments'], correct:1, explanation:'You remain responsible for explaining the code, validating results, catching mistakes, and respecting the interviewer’s AI usage rules.', followUp:'What could go wrong with an AI function that works on one example but fails on an empty string?' },
  { id:39, category:'Debugging & Testing', type:'predict', difficulty:'Beginner', prompt:'What does the second console.log print?', code:'function add(a, b) {\n  console.log(a + b);\n}\nconst answer = add(4, 5);\nconsole.log(answer);', choices:['9','45','undefined','null'], correct:2, explanation:'The function prints 9 internally but does not return it. Assigning its return value to answer stores undefined.', followUp:'How could you both return and display the total?' },
  { id:40, category:'Functions & Strings', type:'mcq', difficulty:'Intermediate', prompt:'Which built-in method best helps remove an exact substring from a string without manually writing a loop?', choices:['replaceAll()','push()','filter()','map()'], correct:0, explanation:'String.replaceAll(search, replacement) can replace every occurrence of a substring. For example, "cheese".replaceAll("e", "") returns "chs". For case-insensitive removal, you must account for both cases or use a suitable regular expression.', followUp:'How might you handle both E and e without converting the entire sentence to lowercase?' }
];
const TRUE_FALSE = ['True', 'False'];
const QUICK_IDS = [1,5,14,16,19,20,28,29,31,33,36,38];
const CATEGORIES = ['Fundamentals','Functions & Strings','Arrays & Objects','Debugging & Testing','Interview Thinking'];

const CHALLENGES = [
  { id:'count-e', title:'Count the letter E', category:'Strings + loops', difficulty:'Beginner', minutes:'5–10 min', description:'Build a function that counts every E or e in a sentence. Return a number instead of printing inside the function.', requirements:['Count uppercase and lowercase E.','Return 0 for a sentence without E.','Return 0 for an empty string.'], starter:'function countE(text) {\n  // TODO: count both E and e\n}\n\nconsole.log(countE("Cheese please!"));', solution:'function countE(text) {\n  let count = 0;\n  for (const letter of text.toLowerCase()) {\n    if (letter === "e") count++;\n  }\n  return count;\n}', tests:[{label:'Lowercase letters',expr:'countE("Cheese please!")',expected:5},{label:'Mixed case',expr:'countE("Eel")',expected:2},{label:'No matches',expr:'countE("pizza")',expected:0},{label:'Empty input',expr:'countE("")',expected:0},{label:'All uppercase',expr:'countE("EEE")',expected:3}], hint:'Try visiting every letter one at a time. Compare it after making the case consistent.' },
  { id:'remove-e', title:'Remove every E', category:'Strings + conditionals', difficulty:'Beginner', minutes:'5–10 min', description:'Return the sentence with every uppercase and lowercase E removed. Preserve all other characters and their original capitalization.', requirements:['Remove E and e.','Keep spaces, punctuation, and other letters.','Return a string.'], starter:'function removeE(text) {\n  // TODO: build a new string\n}\n\nconsole.log(removeE("Cheese please!"));', solution:'function removeE(text) {\n  let result = "";\n  for (const letter of text) {\n    if (letter.toLowerCase() !== "e") result += letter;\n  }\n  return result;\n}', tests:[{label:'Basic sentence',expr:'removeE("Cheese please!")',expected:'Chs plas!'},{label:'Mixed case',expr:'removeE("Eel")',expected:'l'},{label:'Preserves other capitals',expr:'removeE("PEPPER")',expected:'PPPR'},{label:'No matches',expr:'removeE("pizza")',expected:'pizza'},{label:'Empty input',expr:'removeE("")',expected:''}], hint:'Start with an empty string. Add only letters that are not E or e.' },
  { id:'sum-even', title:'Add the even numbers', category:'Arrays + loops', difficulty:'Beginner', minutes:'6–10 min', description:'A restaurant manager wants the total of even-numbered amounts. Add only even values in the array.', requirements:['Return the sum of even values.','Ignore odd values.','An empty array should return 0.'], starter:'function sumEven(numbers) {\n  // TODO: add only even numbers\n}\n\nconsole.log(sumEven([1, 2, 3, 4, 6]));', solution:'function sumEven(numbers) {\n  let total = 0;\n  for (const number of numbers) {\n    if (number % 2 === 0) total += number;\n  }\n  return total;\n}', tests:[{label:'Mixed numbers',expr:'sumEven([1,2,3,4,6])',expected:12},{label:'Only odd numbers',expr:'sumEven([1,3,5])',expected:0},{label:'Empty array',expr:'sumEven([])',expected:0},{label:'Negative numbers',expr:'sumEven([-4,-3,2])',expected:-2},{label:'Zero',expr:'sumEven([0,1,2])',expected:2}], hint:'You need a running total and a way to check the remainder after dividing by 2.' },
  { id:'largest', title:'Find the biggest order', category:'Arrays + comparisons', difficulty:'Beginner', minutes:'7–12 min', description:'Find the largest value in an array of order totals. Return null if there are no orders.', requirements:['Return the largest number.','Handle negative numbers.','Return null for an empty array.'], starter:'function findLargest(numbers) {\n  // TODO: return the largest number\n}\n\nconsole.log(findLargest([12, 45, 8, 23]));', solution:'function findLargest(numbers) {\n  if (numbers.length === 0) return null;\n  let largest = numbers[0];\n  for (const number of numbers) {\n    if (number > largest) largest = number;\n  }\n  return largest;\n}', tests:[{label:'Several positive numbers',expr:'findLargest([12,45,8,23])',expected:45},{label:'All negative numbers',expr:'findLargest([-10,-2,-7])',expected:-2},{label:'Empty input',expr:'findLargest([])',expected:null},{label:'One value',expr:'findLargest([17])',expected:17},{label:'Duplicates',expr:'findLargest([4,4,2])',expected:4}], hint:'Consider what happens if every number is negative. Start with the first actual array value.' },
  { id:'filter-orders', title:'Filter expensive orders', category:'Arrays + objects', difficulty:'Intermediate', minutes:'8–12 min', description:'Return a new array containing only restaurant order objects where total is strictly greater than $20.', requirements:['Keep orders with total > 20, not >= 20.','Return an array of order objects.','Do not modify the original order list.'], starter:'function expensiveOrders(orders) {\n  // TODO: filter orders above $20\n}\n\nconsole.log(expensiveOrders([\n  { item: "Soup", total: 12 },\n  { item: "Steak", total: 30 }\n]));', solution:'function expensiveOrders(orders) {\n  return orders.filter(order => order.total > 20);\n}', tests:[{label:'One matching order',expr:'expensiveOrders([{item:"Soup",total:12},{item:"Steak",total:30}])',expected:[{item:'Steak',total:30}]},{label:'Exactly $20 does not count',expr:'expensiveOrders([{item:"Pasta",total:20}])',expected:[]},{label:'Multiple matches',expr:'expensiveOrders([{id:1,total:25},{id:2,total:40}])',expected:[{id:1,total:25},{id:2,total:40}]},{label:'Empty list',expr:'expensiveOrders([])',expected:[]}], hint:'Which method keeps the items that satisfy a true/false condition?' },
  { id:'finish-tasks', title:'Complete the prep list', category:'Map + objects', difficulty:'Intermediate', minutes:'8–15 min', description:'Return a new array where every task is completed. Do not change the original objects.', requirements:['Every returned task must have completed: true.','Preserve each task’s other properties.','Do not mutate the original tasks or their objects.'], starter:'function finishTasks(tasks) {\n  // TODO: use map to create new objects\n}\n\nconsole.log(finishTasks([\n  { name: "Wash dishes", completed: false },\n  { name: "Prep onions", completed: false }\n]));', solution:'function finishTasks(tasks) {\n  return tasks.map(task => ({\n    ...task,\n    completed: true\n  }));\n}', tests:[{label:'Updates every task',expr:'finishTasks([{name:"Wash",completed:false},{name:"Prep",completed:false}])',expected:[{name:'Wash',completed:true},{name:'Prep',completed:true}]},{label:'Retains extra properties',expr:'finishTasks([{name:"Wash",completed:false,priority:2}])',expected:[{name:'Wash',completed:true,priority:2}]},{label:'Empty list',expr:'finishTasks([])',expected:[]},{label:'Does not mutate original objects',expr:'(() => { const tasks=[{name:"Wash",completed:false}]; finishTasks(tasks); return tasks[0].completed; })()',expected:false}], hint:'map produces a new array, but to avoid changing original objects, make a new object for each task too.' },
  { id:'palindrome', title:'Check a palindrome', category:'Strings + logic', difficulty:'Intermediate', minutes:'8–15 min', description:'Determine if a word reads the same forward and backward. Ignore uppercase vs. lowercase letters; do not worry about spaces or punctuation yet.', requirements:['Return true or false.','Ignore capitalization.','An empty string counts as a palindrome for this exercise.'], starter:'function isPalindrome(text) {\n  // TODO: compare forward and backward text\n}\n\nconsole.log(isPalindrome("Level"));', solution:'function isPalindrome(text) {\n  const word = text.toLowerCase();\n  const reversed = word.split("").reverse().join("");\n  return word === reversed;\n}', tests:[{label:'Mixed-case palindrome',expr:'isPalindrome("Level")',expected:true},{label:'Not a palindrome',expr:'isPalindrome("Burger")',expected:false},{label:'Odd length',expr:'isPalindrome("racecar")',expected:true},{label:'Single character',expr:'isPalindrome("A")',expected:true},{label:'Empty string',expr:'isPalindrome("")',expected:true}], hint:'Can you turn the text backward, then compare it with the original after normalizing case?' },
  { id:'fix-loop', title:'Debug the total', category:'Debugging', difficulty:'Beginner', minutes:'5–8 min', description:'A junior developer wrote a function to add order totals, but the result is NaN. Repair the existing code without rewriting the entire function.', requirements:['Return the sum of array values.','Handle an empty array.','Change as little as necessary.'], starter:'function totalPrices(prices) {\n  let total = 0;\n  for (let i = 0; i <= prices.length; i++) {\n    total += prices[i];\n  }\n  return total;\n}\n\nconsole.log(totalPrices([5, 10]));', solution:'function totalPrices(prices) {\n  let total = 0;\n  for (let i = 0; i < prices.length; i++) {\n    total += prices[i];\n  }\n  return total;\n}', tests:[{label:'Two prices',expr:'totalPrices([5,10])',expected:15},{label:'Empty array',expr:'totalPrices([])',expected:0},{label:'Single price',expr:'totalPrices([9])',expected:9},{label:'Negative numbers',expr:'totalPrices([-5,10])',expected:5}], hint:'For an array of length 2, the valid indexes are 0 and 1. Check the stopping condition.' }
];

const COACH_STEPS = [
  {title:'Clarify the question',body:'Do not explain the problem for Mat. Ask him to clarify inputs, outputs, case sensitivity, and edge cases. Saying a clarifying question out loud is a success.'},
  {title:'Talk before typing',body:'Have Mat describe his algorithm in two or three sentences. If he gets stuck, ask what the smallest possible example would be.'},
  {title:'Run and inspect',body:'Have him predict the output, run the code, and compare. Ask which line made the result appear. A test that fails is useful information.'},
  {title:'Review and adapt',body:'Once it works, change one requirement. Ask him to explain what must change, test again, and explain one tradeoff or edge case.'}
];
const COACH_PROMPTS = [
  ['Walk me through a project you built.','Listen for: the problem, his own contribution, languages or tools, one difficult decision, what was tested, and what he learned. Do not accept only a list of technologies.'],
  ['Tell me about a bug that took time to solve.','Listen for: how he reproduced the issue, hypotheses he checked, changes he made, and how he verified the fix. Restaurant examples work for behavior; code examples are better for technical debugging.'],
  ['What is the difference between a parameter and an argument?','Parameter: named placeholder in the function definition. Argument: actual value supplied during the function call. Example: name versus "Mat".'],
  ['What is the difference between return and console.log()?','return hands a value back to the caller; console.log displays a value. Logging does not automatically return that value.'],
  ['How are map(), filter(), and find() different?','map: create a new array by transforming every item. filter: create a new array of matching items. find: return the first matching item or undefined.'],
  ['What would you do if assigned unfamiliar technology?','Good answer: clarify the task, look for existing code and documentation, make the smallest example, test, ask targeted questions after trying, and keep stakeholders informed.'],
  ['How would you check a solution generated by AI?','Good answer: read every part, compare with requirements, test ordinary and edge cases, understand dependencies/security consequences, and follow employer tool-use rules.'],
  ['What should you do when stuck in a live interview?','Stay communicative. Restate the known facts, simplify the problem, test a small example, articulate where you are blocked, and ask a focused question.'],
  ['What are good edge cases for countE(text)?','Empty text, no matches, uppercase E, lowercase e, mixed case, punctuation, long input, and potentially non-string input if required by contract.'],
  ['What is your most useful experience from restaurant work?','Look for a specific real incident demonstrating communication, prioritization, teamwork, quality control, customer focus, or handling ambiguity. Encourage a Challenge → Action → Result story.']
];

const STORAGE_KEY = 'mats-interview-lab-state-v1';
function emptyState(){return { view:'home', answers:{}, choices:{}, flagged:{}, codeDrafts:{}, codeRuns:{}, codeSolved:{}, attemptedCode:{}, focus:false };}
function restoreState(){try {const data=JSON.parse(localStorage.getItem(STORAGE_KEY)); if(data&&typeof data==='object')return {...emptyState(),...data};} catch(err){} return emptyState();}
let state = restoreState();
let quizSet = 'quick';
let quizCategory = 'All topics';
let quizIndex = 0;
let challengeId = CHALLENGES[0].id;
let running = false;
let activeWorker = null;
let timer = null;
let toastTimer = null;
const app = document.getElementById('app');
const safe = (v)=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(err){}}
function stats(){const submissions=QUESTIONS.filter(q=>state.answers[q.id]?.submitted);const correct=submissions.filter(q=>state.answers[q.id].selected===q.correct);const passed=CHALLENGES.filter(c=>state.codeSolved[c.id]);return {done:submissions.length,correct:correct.length,accuracy:submissions.length?Math.round(100*correct.length/submissions.length):0,coding:passed.length};}
function currentQuestions(){let list=quizSet==='quick'?QUICK_IDS.map(id=>QUESTIONS.find(q=>q.id===id)):QUESTIONS; return quizCategory==='All topics'?list:list.filter(q=>q.category===quizCategory);}
function getChoices(q){return q.type==='tf'?TRUE_FALSE:q.choices;}
function choiceLabel(q,index){return getChoices(q)[index] ?? ''}
function isSubmitted(q){return Boolean(state.answers[q.id]?.submitted)}
function countCategory(category){return QUESTIONS.filter(q=>q.category===category).length;}
function notice(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800);}
function navigate(view){state.view=view;save();render();window.scrollTo({top:0,behavior:'instant'});}
function render(){document.body.classList.toggle('focus-mode',!!state.focus);document.getElementById('focus-toggle').innerHTML=state.focus?'◧ <span>Show menu</span>':'⛶ <span>Focus view</span>';document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===state.view));document.getElementById('page-location').textContent=({'home':'OVERVIEW','quiz':'QUESTION BANK','code':'CODE LAB','coach':'COACH’S GUIDE','results':'RESULTS'})[state.view]??'OVERVIEW';document.getElementById('bank-count').textContent=String(QUESTIONS.length);if(state.view==='home')renderHome();else if(state.view==='quiz')renderQuiz();else if(state.view==='code')renderCode();else if(state.view==='coach')renderCoach();else if(state.view==='results')renderResults();else navigate('home');}

function renderHome(){const s=stats();app.innerHTML=`
  <section class="hero"><div class="hero-copy"><div class="eyebrow">THE PRACTICE SPACE FOR FUTURE DEVELOPERS</div><h1>Think it. Code it.<br><em>Prove it works.</em></h1><p>A focused technical interview studio for Mat and Joe. Predict the answer, commit it, learn why, then solve real JavaScript challenges together.</p><div class="hero-actions"><button class="button primary" data-action="start-quiz">Start mock interview <span aria-hidden="true">↗</span></button><button class="button secondary" data-view="code">Open code lab ↗</button></div></div><div class="hero-decoration" aria-hidden="true"><div class="hero-card-float one"><span class="comment">// Your next interview</span><br><span class="key">function</span> <span class="str">thinkFirst</span>() {<br>&nbsp; <span class="key">return</span> <span class="str">"I got this."</span>;<br>}</div><div class="hero-card-float two"><span class="comment">✓ Tested with confidence</span><br><span class="str">4 / 4 test cases passed</span><br><span class="comment">Ready for next challenge →</span></div></div></section>
  <section class="stat-grid" aria-label="Session progress"><div class="stat-card"><div class="stat-top"><i class="stat-dot"></i> Questions answered</div><div class="stat-number">${s.done}<span> / ${QUESTIONS.length}</span></div></div><div class="stat-card"><div class="stat-top"><i class="stat-dot" style="background:var(--cyan)"></i> Quiz accuracy</div><div class="stat-number">${s.accuracy}<span>%</span></div></div><div class="stat-card"><div class="stat-top"><i class="stat-dot" style="background:var(--lime)"></i> Coding challenges solved</div><div class="stat-number">${s.coding}<span> / ${CHALLENGES.length}</span></div></div></section>
  <div class="section-head"><h2>Today's practice plan</h2><small>About 45–60 minutes · adaptable</small></div>
  <section class="content-grid"><div class="surface pad"><h3 class="surface-title">The interview workout</h3><p class="surface-sub">Built for real conversation, not just memorizing answers.</p><div class="track"><div class="track-row"><div class="track-n">01</div><div><strong>Warm up with questions</strong><span>True / false, multiple choice, and output prediction</span></div><div class="track-time">15 min</div></div><div class="track-row"><div class="track-n">02</div><div><strong>Write and run JavaScript</strong><span>8 problems with immediate test feedback</span></div><div class="track-time">25 min</div></div><div class="track-row"><div class="track-n">03</div><div><strong>Explain the why</strong><span>Discuss bugs, edge cases, and project stories</span></div><div class="track-time">15 min</div></div></div><button class="button secondary top-gap" data-view="coach">View coach instructions ↗</button></div><div class="surface pad"><h3 class="surface-title">Skills you'll practice</h3><p class="surface-sub">From first principles to interview reasoning.</p><div class="topic-list">${CATEGORIES.map(c=>`<span class="topic-chip"><span>●</span> ${safe(c)} · ${countCategory(c)}</span>`).join('')}</div><div class="info-banner top-gap"><strong>Important:</strong> Questions are original practice examples, not actual LaunchCode exam questions. An employer may allow or prohibit AI during the real interview.</div></div></section>`;}
function renderQuiz(){const list=currentQuestions(); if(quizIndex>=list.length)quizIndex=Math.max(0,list.length-1);const q=list[quizIndex];const selected=q?state.choices[q.id]:undefined;const submitted=q&&isSubmitted(q);const response=submitted?state.answers[q.id]:null;const filteredDone=list.filter(x=>isSubmitted(x)).length;const filteredRight=list.filter(x=>isSubmitted(x)&&state.answers[x.id].selected===x.correct).length; app.innerHTML=`
  <div class="eyebrow">INTERACTIVE QUESTION BANK</div><h1 class="page-heading">One question. One answer.<br>One lesson at a time.</h1><p class="page-description">Choose an answer and click <strong>Submit answer</strong>. Only then will the correct choice and explanation appear. Use Focus view to screen-share without the sidebar.</p>
  <div class="filterbar"><div class="filtergroup"><label class="micro-info" for="quiz-set">PRACTICE SET</label><select id="quiz-set" class="select" aria-label="Practice set"><option value="quick" ${quizSet==='quick'?'selected':''}>Quick interview · 12</option><option value="all" ${quizSet==='all'?'selected':''}>Full question bank · ${QUESTIONS.length}</option></select><select id="quiz-category" class="select" aria-label="Topic category"><option value="All topics">All topics</option>${CATEGORIES.map(c=>`<option value="${safe(c)}" ${quizCategory===c?'selected':''}>${safe(c)}</option>`).join('')}</select></div><div class="micro-info">${filteredDone} of ${list.length} submitted</div></div>
  ${!q?'<div class="empty-state">No questions match this selection. Choose another practice set or topic.</div>':`<section class="quiz-layout"><div class="quiz-card"><div class="quiz-card-inner"><div class="quiz-topline"><span class="small-pill accent">QUESTION ${quizIndex+1} / ${list.length}</span><span class="small-pill">${safe(q.category)}</span><span class="small-pill purple">${safe(q.difficulty)}</span></div><div class="question-kicker">${q.type==='tf'?'TRUE OR FALSE':q.type==='predict'?'PREDICT THE OUTPUT':'MULTIPLE CHOICE'}</div><h2 class="question-text">${safe(q.prompt)}</h2>${q.code?`<pre class="code-snippet"><code>${safe(q.code)}</code></pre>`:''}<div class="choice-list" role="group" aria-label="Answer choices">${getChoices(q).map((c,i)=>`<button type="button" class="choice ${selected===i?'selected':''} ${submitted&&i===q.correct?'correct':''} ${submitted&&selected===i&&i!==q.correct?'incorrect':''}" data-choice="${i}" aria-pressed="${selected===i}" ${submitted?'disabled':''}><span class="choice-key">${String.fromCharCode(65+i)}</span><span>${safe(c)}</span>${submitted&&i===q.correct?'<span class="choice-mark" aria-label="Correct">✓</span>':''}${submitted&&selected===i&&i!==q.correct?'<span class="choice-mark" aria-label="Incorrect">×</span>':''}</button>`).join('')}</div>${submitted?`<div class="feedback ${response.selected===q.correct?'':'bad'}" role="status"><div class="feedback-heading">${response.selected===q.correct?'✓ That’s correct!':'↗ Not quite. Here’s why.'}</div><p><strong>Correct answer: ${safe(choiceLabel(q,q.correct))}</strong></p><p>${safe(q.explanation)}</p><div class="coach-prompt"><strong>Discuss it together:</strong> ${safe(q.followUp)}</div></div>`:''}</div><div class="question-controls"><div class="inline-actions"><button class="button ghost" data-action="previous" ${quizIndex===0?'disabled':''}>← Previous</button><button class="flag-btn ${state.flagged[q.id]?'active':''}" data-action="flag">${state.flagged[q.id]?'★ Flagged to revisit':'☆ Flag to revisit'}</button></div><div class="inline-actions">${!submitted?`<button class="button primary" data-action="submit" ${selected===undefined?'disabled':''}>Submit answer ↗</button>`:''}<button class="button ${submitted?'primary':'secondary'}" data-action="next" ${quizIndex===list.length-1?'disabled':''}>Next question →</button>${quizIndex===list.length-1?'<button class="button secondary" data-view="results">See results ↗</button>':''}</div></div></div>
  <aside class="aside-panel" aria-label="Session overview"><div class="aside-header"><strong>Session progress</strong><span>${filteredDone}/${list.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${list.length?Math.round(100*filteredDone/list.length):0}%"></div></div><div class="question-nav-grid">${list.map((x,i)=>{let className='';if(isSubmitted(x))className=state.answers[x.id].selected===x.correct?'done-good':'done-bad';return `<button type="button" class="q-jump ${className} ${i===quizIndex?'current':''} ${state.flagged[x.id]?'flagged':''}" data-jump="${i}" aria-label="Question ${i+1}${isSubmitted(x)?' answered':''}" title="Question ${i+1}">${i+1}</button>`}).join('')}</div><div class="aside-divider"></div><div class="result-strip"><div><strong>${filteredRight}</strong>Correct</div><div><strong>${filteredDone-filteredRight}</strong>Missed</div><div><strong>${Object.values(state.flagged).filter(Boolean).length}</strong>Flagged</div></div><div class="aside-divider"></div><p class="aside-note"><strong>Coach's tip</strong><br>Before clicking Submit, have Mat explain <em>why</em> he chose that answer. On a wrong answer, ask him to predict what would happen if one line changed.</p><button class="button ghost" style="width:100%;margin-top:7px" data-view="results">View all results ↗</button></aside></section>`}`;}

function renderCode(){const ch=CHALLENGES.find(c=>c.id===challengeId)||CHALLENGES[0];const draft=state.codeDrafts[ch.id]??ch.starter;const result=state.codeRuns[ch.id];const attempts=state.attemptedCode[ch.id]||0;app.innerHTML=`
  <div class="eyebrow">HANDS-ON JAVASCRIPT</div><h1 class="page-heading">Write code. Run tests.<br>Understand the result.</h1><p class="page-description">This is a working JavaScript practice environment. Edit the file, run it, and see actual test results — no Replit, installation, or backend needed.</p>
  <div class="info-banner top-gap"><strong>How this works:</strong> Each challenge provides a starter <code>index.js</code>. Write the missing logic, then click <strong>Run & test</strong>. Your code runs in a temporary browser worker. The example solution stays hidden until after your first attempt.</div>
  <section class="lab-layout"><aside class="challenge-list" aria-label="Coding challenges">${CHALLENGES.map((c,i)=>`<button class="challenge-link ${c.id===ch.id?'active':''} ${state.codeSolved[c.id]?'done':''}" data-challenge="${safe(c.id)}"><strong>${String(i+1).padStart(2,'0')} · ${safe(c.title)}</strong><small>${state.codeSolved[c.id]?'✓ All tests passed':safe(c.category)+' · '+safe(c.minutes)}</small></button>`).join('')}</aside><div class="lab-main"><div class="lab-intro"><div class="quiz-topline"><span class="small-pill accent">${safe(ch.difficulty)}</span><span class="small-pill">${safe(ch.minutes)}</span><span class="small-pill purple">${ch.tests.length} hidden checks after running</span></div><h2>${safe(ch.title)}</h2><p>${safe(ch.description)}</p><ul class="requirements">${ch.requirements.map(r=>`<li>${safe(r)}</li>`).join('')}</ul></div><div class="editor-panel"><div class="editor-header"><div class="file-tab">● &nbsp; index.js</div><div class="editor-meta">JAVASCRIPT · AUTO-SAVED IN BROWSER</div></div><textarea class="code-editor" id="code-editor" aria-label="Edit JavaScript code" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off">${safe(draft)}</textarea><div class="editor-toolbar"><button class="button primary" id="run-code" data-action="run-code" ${running?'disabled':''}>▶ &nbsp;${running?'Running...':'Run & test'}</button><button class="button secondary" data-action="reset-code">↻ Reset starter</button><button class="button ghost" data-action="copy-code">Copy code</button><button class="button ghost" data-action="hint">Need a hint?</button></div></div>${result?renderTestResults(result,ch):'<div class="test-results"><div class="test-title"><strong>Test results</strong><span>Ready to run</span></div><div class="output-area"><div class="terminal">$ node index.js\n<span class="muted">// Your output and test results will appear here.</span></div></div></div>'}${attempts>0?`<details class="solution-wrap"><summary>Reveal an example solution (after attempting)</summary><pre class="code-snippet"><code>${safe(ch.solution)}</code></pre><p class="micro-info">This is one working solution, not the only possible approach. Explain why it passes before copying it.</p></details>`:'<p class="micro-info top-gap">Example solution unlocks after your first run.</p>'}</div></section>`;}
function renderTestResults(result,ch){const passed=result.tests.filter(t=>t.passed).length;return `<div class="test-results" aria-live="polite"><div class="test-title"><strong>Test results ${result.timeout?'· execution stopped':''}</strong><span>${passed} / ${ch.tests.length} checks passed</span></div><div class="test-list">${result.tests.length?result.tests.map(t=>`<div class="test-row"><span class="test-bullet ${t.passed?'pass':'fail'}">${t.passed?'✓':'×'}</span><div><strong>${safe(t.label)}</strong><small>${t.error?safe(t.error):`Expected ${safe(t.expected)} · Got ${safe(t.actual)}`}</small></div></div>`).join(''):`<div class="test-row"><span class="test-bullet fail">×</span><div><strong>${result.error?'Execution error':'No test results'}</strong><small>${safe(result.error||'Run the code again.')}</small></div></div>`}</div><div class="output-area"><div class="micro-info">CONSOLE OUTPUT</div><pre class="terminal">${safe(result.logs.length?result.logs.join('\n'):'(no console.log output)')}${result.error?'\nERROR: '+safe(result.error):''}</pre></div></div>`;}

function renderCoach(){app.innerHTML=`<div class="eyebrow">FACILITATOR PLAYBOOK</div><h1 class="page-heading">You lead the interview.<br>Mat does the thinking.</h1><p class="page-description">Use this page as your private guide while screen-sharing. The ideal practice cycle is: explain the problem → predict → write → test → explain why.</p><div class="coach-grid">${COACH_STEPS.map((st,i)=>`<div class="coach-card"><div class="step-id">STEP ${String(i+1).padStart(2,'0')}</div><h3>${safe(st.title)}</h3><p>${safe(st.body)}</p></div>`).join('')}</div><div class="section-head"><h2>Ask it aloud. Then reveal what to listen for.</h2><small>Answers are collapsed by default</small></div><section class="accordion-group">${COACH_PROMPTS.map(([q,a],i)=>`<details class="accordion"><summary>${String(i+1).padStart(2,'0')} &nbsp; ${safe(q)}</summary><p>${safe(a)}</p></details>`).join('')}</section><div class="section-head"><h2>How to run a useful 60-minute session</h2></div><div class="surface pad"><div class="track"><div class="track-row"><div class="track-n">10</div><div><strong>Concept checks</strong><span>True/false, terms, and explain-the-output questions</span></div><div class="track-time">min</div></div><div class="track-row"><div class="track-n">25</div><div><strong>Code problems</strong><span>Count E → remove E → one array/object problem</span></div><div class="track-time">min</div></div><div class="track-row"><div class="track-n">15</div><div><strong>Debugging and code review</strong><span>Choose a broken implementation; require the smallest fix</span></div><div class="track-time">min</div></div><div class="track-row"><div class="track-n">10</div><div><strong>Project storytelling</strong><span>One project, one hard bug, one lesson learned</span></div><div class="track-time">min</div></div></div></div><div class="info-banner top-gap"><strong>Source note:</strong> This is an independent practice experience inspired by common entry-level software interview skills, not an official LaunchCode exam. For LaunchCode's own interview approach, visit <a href="https://education.launchcode.org/career-readiness/interviews/live-coding.html" target="_blank" rel="noopener noreferrer">the Live Coding Playbook</a> and <a href="https://education.launchcode.org/liftoff/modules/career/tech-interview.html" target="_blank" rel="noopener noreferrer">Mastering the Technical Interview</a>. Individual employers may use different formats.</div>`;}

function renderResults(){const s=stats();const cats=CATEGORIES.map(name=>{const qs=QUESTIONS.filter(q=>q.category===name);const done=qs.filter(q=>isSubmitted(q));const right=done.filter(q=>state.answers[q.id].selected===q.correct);return {name,total:qs.length,done:done.length,right:right.length};});const missed=QUESTIONS.filter(q=>isSubmitted(q)&&state.answers[q.id].selected!==q.correct);app.innerHTML=`
  <div class="eyebrow">SESSION DEBRIEF</div><h1 class="page-heading">Progress you can explain.</h1><p class="page-description">See where the practice is sticking, review missed questions, and choose what to do next. Scores update when an answer is submitted.</p><div class="results-hero top-gap"><div><div class="eyebrow">CURRENT ACCURACY</div><div class="results-big">${s.accuracy}% <small>correct</small></div><p class="surface-sub">${s.correct} correct answers out of ${s.done} submitted · ${s.coding} of ${CHALLENGES.length} coding labs passed</p></div><div class="hero-actions"><button class="button primary" data-view="quiz">Continue question bank ↗</button><button class="button secondary" data-view="code">Open coding lab ↗</button></div></div><div class="section-head"><h2>Performance by topic</h2></div><section class="surface pad"><div class="results-bars">${cats.map(c=>`<div class="bar-row"><span>${safe(c.name)}</span><div class="progress-track" style="margin:0"><div class="progress-fill" style="width:${c.total?Math.round(100*c.right/c.total):0}%"></div></div><strong>${c.right}/${c.total}</strong></div>`).join('')}</div><p class="micro-info top-gap">Bars show correct answers divided by all questions in each topic. Unanswered questions are included in the denominator.</p></section><div class="section-head"><h2>Questions to revisit</h2><small>${missed.length} missed · ${Object.values(state.flagged).filter(Boolean).length} flagged</small></div><div class="review-list">${[...new Map([...missed,...QUESTIONS.filter(q=>state.flagged[q.id])].map(q=>[q.id,q])).values()].length?[...new Map([...missed,...QUESTIONS.filter(q=>state.flagged[q.id])].map(q=>[q.id,q])).values()].map(q=>`<button class="review-row" data-review="${q.id}"><span class="review-dot ${isSubmitted(q)?(state.answers[q.id].selected===q.correct?'good':'bad'):''}"></span><div><strong>${safe(q.prompt)}</strong><small>${safe(q.category)} · Question ${q.id}</small></div><span class="review-arrow">↗</span></button>`).join(''):'<div class="empty-state">Nothing to review yet. Answer a few questions, or flag a topic for later.</div>'}</div>`;}

function switchChallenge(id){if(!CHALLENGES.some(c=>c.id===id))return;challengeId=id;render();}
function resetCode(){const ch=CHALLENGES.find(c=>c.id===challengeId);if(!confirm('Reset this editor back to the starter code? Your changes to this challenge will be lost.'))return;delete state.codeDrafts[ch.id];delete state.codeRuns[ch.id];delete state.codeSolved[ch.id];delete state.attemptedCode[ch.id];save();render();}
function runCode(){if(running)return;const ch=CHALLENGES.find(c=>c.id===challengeId);const editor=document.getElementById('code-editor');if(!editor)return;const code=editor.value;state.codeDrafts[ch.id]=code;state.attemptedCode[ch.id]=(state.attemptedCode[ch.id]||0)+1;save();running=true;const button=document.getElementById('run-code');if(button){button.disabled=true;button.textContent='Running tests...';}const workerScript=`'use strict';\nself.onmessage = function(ev) {\n  const { code, tests, id } = ev.data;\n  const logs = []; const results = []; let error = null;\n  const format = v => { try { return typeof v === 'string' ? v : JSON.stringify(v) ?? String(v); } catch(e) { return String(v); } };\n  const fakeConsole = { log: (...args) => logs.push(args.map(format).join(' ')), error: (...args) => logs.push(args.map(format).join(' ')) };\n  const compare = (a,b) => JSON.stringify(a) === JSON.stringify(b);\n  const check = (label, actual, expected) => { results.push({label,passed:compare(actual,expected),actual:format(actual),expected:format(expected)}); };\n  const failed = (label,e,expected) => { results.push({label,passed:false,error:String(e && e.message || e),expected:format(expected),actual:'(error)'}); };\n  try {\n    const testCode=tests.map(t=>'try { __check('+JSON.stringify(t.label)+', ('+t.expr+'), '+JSON.stringify(t.expected)+'); } catch(__err) { __failed('+JSON.stringify(t.label)+', __err, '+JSON.stringify(t.expected)+'); }').join('\\n');\n    const fn = new Function('console','__check','__failed','"use strict";\\n'+code+'\\n'+testCode);\n    fn(fakeConsole, check, failed);\n  } catch(e) { error = String(e && e.message || e); }\n  self.postMessage({id,logs,tests:results,error});\n};`;
  try{const objectUrl=URL.createObjectURL(new Blob([workerScript],{type:'text/javascript'}));const worker=new Worker(objectUrl);URL.revokeObjectURL(objectUrl);activeWorker=worker;const requestId=ch.id+'-'+Date.now();const finish=(data)=>{if(!running)return;clearTimeout(timer);worker.terminate();activeWorker=null;running=false;state.codeRuns[ch.id]=data;if(data.tests.length===ch.tests.length&&data.tests.every(t=>t.passed)&&!data.error&&!data.timeout)state.codeSolved[ch.id]=true;else state.codeSolved[ch.id]=false;save();if(state.view==='code'&&challengeId===ch.id){const old=document.getElementById('code-editor')?.value;render();const newEditor=document.getElementById('code-editor');if(newEditor&&old!==undefined)newEditor.value=old;}if(data.tests.every(t=>t.passed)&&data.tests.length===ch.tests.length&&!data.error&&!data.timeout)notice('All tests passed! Nice work.');};worker.onmessage=e=>{if(e.data?.id!==requestId)return;finish(e.data)};worker.onerror=e=>{finish({id:requestId,logs:[],tests:[],error:e.message||'The code worker could not run.'});};timer=setTimeout(()=>finish({id:requestId,logs:[],tests:[],error:'Code exceeded the 3-second limit. Check for an infinite loop.',timeout:true}),3000);worker.postMessage({id:requestId,code,tests:ch.tests});}catch(err){running=false;clearTimeout(timer);const data={id:ch.id,logs:[],tests:[],error:err.message||String(err)};state.codeRuns[ch.id]=data;save();render();notice('Could not start code runner in this browser.');}}

function resetSession(){if(!confirm('Clear all answers, test results, code edits, and scores in this browser?'))return;if(activeWorker)activeWorker.terminate();clearTimeout(timer);running=false;state=emptyState();quizSet='quick';quizCategory='All topics';quizIndex=0;challengeId=CHALLENGES[0].id;save();render();notice('Session reset. Ready to practice.');}

document.addEventListener('click',async e=>{
 const viewButton=e.target.closest('[data-view]');if(viewButton){navigate(viewButton.dataset.view);return;}
 const action=e.target.closest('[data-action]');if(action){const a=action.dataset.action;if(a==='start-quiz'){quizSet='quick';quizCategory='All topics';quizIndex=0;navigate('quiz');}else if(a==='previous'){quizIndex=Math.max(0,quizIndex-1);render();}else if(a==='next'){quizIndex=Math.min(currentQuestions().length-1,quizIndex+1);render();}else if(a==='submit'){const q=currentQuestions()[quizIndex];if(!q||state.choices[q.id]===undefined||isSubmitted(q))return;state.answers[q.id]={submitted:true,selected:state.choices[q.id]};save();render();}else if(a==='flag'){const q=currentQuestions()[quizIndex];if(!q)return;state.flagged[q.id]=!state.flagged[q.id];save();render();}else if(a==='reset-code')resetCode();else if(a==='run-code')runCode();else if(a==='hint'){const ch=CHALLENGES.find(c=>c.id===challengeId);notice(ch.hint);}else if(a==='copy-code'){const code=document.getElementById('code-editor')?.value||'';try{await navigator.clipboard.writeText(code);notice('Code copied to clipboard.');}catch(err){notice('Select the code and copy manually.');}}return;}
 const choice=e.target.closest('[data-choice]');if(choice){const q=currentQuestions()[quizIndex];if(q&&!isSubmitted(q)){state.choices[q.id]=Number(choice.dataset.choice);save();render();}return;}
 const jump=e.target.closest('[data-jump]');if(jump){quizIndex=Number(jump.dataset.jump);render();return;}
 const choose=e.target.closest('[data-challenge]');if(choose){switchChallenge(choose.dataset.challenge);return;}
 const review=e.target.closest('[data-review]');if(review){quizSet='all';quizCategory='All topics';quizIndex=QUESTIONS.findIndex(q=>q.id===Number(review.dataset.review));navigate('quiz');return;}
 if(e.target.closest('#reset-session')){resetSession();return;}
 if(e.target.closest('#focus-toggle')){state.focus=!state.focus;save();render();}
});
document.addEventListener('change',e=>{if(e.target.id==='quiz-set'){quizSet=e.target.value;quizIndex=0;render();}if(e.target.id==='quiz-category'){quizCategory=e.target.value;quizIndex=0;render();}});
document.addEventListener('input',e=>{if(e.target.id==='code-editor'){state.codeDrafts[challengeId]=e.target.value;save();}});
document.addEventListener('keydown',e=>{if(e.target?.id==='code-editor'&&e.key==='Tab'){e.preventDefault();const el=e.target;const start=el.selectionStart;const end=el.selectionEnd;el.value=el.value.substring(0,start)+'  '+el.value.substring(end);el.selectionStart=el.selectionEnd=start+2;state.codeDrafts[challengeId]=el.value;save();}});
render();
